INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3732915512, 40, 'Ardor Session', 'General', 'Junk', 'Common', 'An electric guitar.', 1, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3639749796, 35, 'Armadillo', 'Recipe', 'Misc', 'Random', 'Allows you to craft a clothing mod.', 1, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3985372862, 24, 'Armagnac Massy', 'Consumable', 'Edible', 'Common', 'Don''t drink it. Savor it.', 1, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (380884973, 23, 'Armor-plated syn-leather solo pants', 'Clothing', 'Legs', 'Legendary', 'After a few months on the Street, I got into a dustdown with a local Booster lord. I flatlined him and went back to my drink. Within ten minutes, the recruiter from Militech came up to me and dropped a business card... Now I’m a company man. – Morgan Blackhand, Solo', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1106857470, 24, 'Armor-quilted jacket', 'Clothing', 'Outer chest', 'Random', 'A flashback to the 20th century.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3340047069, 20, 'Armor-weave long vest', 'Clothing', 'Outer chest', 'Random', 'The brass knuckles on the back fulfill both an aesthetic and warning function.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1567610082, 29, 'Armored Berserk', 'Recipe', 'Misc', 'Random', 'Allows you to craft a cyberware mod.', 1, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2848283888, 22, 'Armored Berserk', 'Part', 'Fragment', 'Random', NULL, 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3850732614, 23, 'Armored media ocuset with camera', 'Clothing', 'Face', 'Legendary', 'I used to watch those reporters on the TV news. They wore those chill trenchcoats and were always broadcasting from some exotic place like Mozambique or Saigon. They went right into the Cenral American warzones with the cybergrunts, and they got the story even when shooting was maximally fierce. That’s the part I like; the danger. – Lyle McClellan, Network 54', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3865310297, 22, 'Armored tac vest with camo lining', 'Clothing', 'Outer chest', 'Random', 'For bona fide professionals.', 2, 1);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (4121336150, 29, 'Armorweave rocker bra', 'Clothing', 'Inner chest', 'Legendary', 'There were these scum out there who were messing with the world. They were killing people, raping the land, and lying in our faces when we caught ''em. Music always gets hammered down to the Three A’s. Axe, Attitude and Audience. Me, I had an Axe and an Attitude. All I had to do was get the third one... – Kerry Eurodyne, Rockerboy', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3735306793, 23, 'Army Star anti-chafing cargo pants', 'Clothing', 'Legs', 'Random', 'Classic militarism with a punch.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3841419137, 23, 'Army-J3w3L polycarbonate tactical flight jacket', 'Clothing', 'Outer chest', 'Random', 'Who needs netrunning skills to blind your enemies when you have this?', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1603920411, 27, 'Arte Urbano elegantly nanostitched shirt', 'Clothing', 'Outer chest', 'Random', 'Becoming a walking, talking piece of abstract art!', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (269885344, 23, 'Artichoke ''n'' Avocado Pizza', 'Consumable', 'Edible', 'Common', 'Topping it to the next level.', 1, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3100139308, 21, 'Arumajiro dual-armor aramid breastplate', 'Clothing', 'Outer chest', 'Random', 'The higher the price, the better your chances of survival.', 2, 0);
