INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3133823122, 33, 'Attention! A new directive is now in force!\n\nBecause Jago''s rats will no longer be wearings masks, this means you must wear yours at all times. Whether you''re on duty, in the shower or on the shitter – your masks stay on. If I see anyone without their mask, they''ll get a bullet between the eyes.\n\nLt. Col. Bennett', 'General', 'Readable', 'Common', NULL, 1, 1);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (4249186729, 42, 'Attention! As you may have noticed, Dogtown has an infestation problem. If you see anyone with a spray can or poster in hand... you know what to do. If you hear anyone shouting suspicious words or phrases – same thing. It''s time to clean up Dogtown, so grab your shovels and get this shit off our streets.\n\nLt. Col. Bennett', 'General', 'Readable', 'Common', NULL, 1, 1);
