INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (472313674, 25, 'Duolayer microplate-mesh nomad jacket', 'Clothing', 'Outer chest', 'Legendary', 'We don’t have a home except the Caravan. We don’t have rights except what we take. We get run out of town by the cops; we get raided by the roadwarrior packs, and we survive because we’ve got guns and bikes…There’s kids, old men and women—families here. This ain’t no boostergang. These people are my family. – Nomad Santiago', 2, 0);
