INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1250836528, 30, 'Elastiweave fixer pumps with reinforced seams', 'Clothing', 'Feet', 'Legendary', 'Don’t give me this "Robin Hood" stuff. I’m doin’ a job, no more. I give people what they want, an’ they pay me out. Maybe I even a few scores here and there, but that’s good for business. I got a slogan... “How much you pay me? – Phil "Nacho" Hernandez, Fixer', 2, 0);
