INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1230640006, 22, 'Heat-resistant Killer Candy trilayer racers', 'Clothing', 'Legs', 'Random', 'Sweet and deadly.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2039898997, 25, 'Heat-resistant aramid-weave fixer bustier', 'Clothing', 'Inner chest', 'Legendary', 'Don’t give me this "Robin Hood" stuff. I’m doin’ a job, no more. I give people what they want, an’ they pay me out. Maybe I even a few scores here and there, but that’s good for business. I got a slogan... “How much you pay me? – Phil "Nacho" Hernandez, Fixer', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2064206288, 22, 'Heat-resistant dress with lead-glass sleeves', 'Clothing', 'Outer chest', 'Random', 'Bartenders will be tipping YOU.', 2, 1);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1303463981, 31, 'Heat-resistant hybridweave netrunning suit', 'Clothing', 'Inner chest', 'Legendary', 'I think they had some weeflerunner playin’ Sysop for them. I burned in, jolted the guy with a borrowed Hellbolt, and did the major plunder action all over the Data Fortress. You guys who live in Realspace; you move so slow. Me, I like Netspace. It moves fast. You don''t get old, you don''t get slow and sloppy. You just leave the meat and go screamin''. – Spider Murphy', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (689665009, 20, 'Heat-resistant long vest', 'Clothing', 'Outer chest', 'Random', 'Not all that glitters is gold. Sometimes it''s silver.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2816647785, 23, 'Heat-resistant military boots', 'Clothing', 'Feet', 'Random', 'Designed with urban operations in mind.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3888136265, 24, 'Heat-resistant nanoweave media shirt', 'Clothing', 'Inner chest', 'Legendary', 'I used to watch those reporters on the TV news. They wore those chill trenchcoats and were always broadcasting from some exotic place like Mozambique or Saigon. They went right into the Cenral American warzones with the cybergrunts, and they got the story even when shooting was maximally fierce. That’s the part I like; the danger. – Lyle McClellan, Network 54', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1033679793, 21, 'Heat-resistant nylon shinos', 'Clothing', 'Legs', 'Random', 'Like they were forged in the great fires of industry.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (147171681, 22, 'Heat-resistant reinforced Nu-Tek tight tank', 'Clothing', 'Inner chest', 'Random', 'For working out in. Not social calls.', 2, 0);
