INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (646175964, 21, 'Heavy hybrid-armor Trickster coat', 'Clothing', 'Outer chest', 'Random', 'Get out onto the streets and make some noise!', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (188160, 24, 'Heavy shock-absorbent solo jacket', 'Clothing', 'Outer chest', 'Legendary', 'After a few months on the Street, I got into a dustdown with a local Booster lord. I flatlined him and went back to my drink. Within ten minutes, the recruiter from Militech came up to me and dropped a business card... Now I’m a company man. – Morgan Blackhand, Solo', 2, 0);
