INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2411624829, 23, 'Heavy-duty aramid-reinforced badge coat', 'Clothing', 'Outer chest', 'Legendary', 'Give it up, punk. And I don''t want to hear some sob story about how it was "society" that drove you to this. I just want to see that gun on the ground. Right now... before I give you an extra nostril. - Sgt. Max Hammerman, NCPD', 2, 0);
