INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (642696237, 39, 'Militech "Apogee" Sandevistan', 'Cyberware', NULL, 'Legendary++', 'This model of Sandevistan doesn''t exist, at least officially. Off the record, there''s gossip of secret Militech Lunar labs producing covert cyberware. It was never meant to be mass produced, but an army would only really need a few pieces like this one to dominate their enemy.', 2, 1);
