INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2824225, 27, 'Militech Canto Mk.6', 'Cyberware', NULL, 'Rare', 'A rare cyberdeck model with unique Militech-produced components. This gear was allegedly used in the secret Cynosure project. Fun fact: the model’s name is a reference to Dante’s "Divine Comedy". In the sixth canto, Dante descends into Inferno’s third circle, guarded by the three-headed beast Cerberus.', 2, 1);
