INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (2113376456, 19, 'Polyamide-reinforced conical hat', 'Clothing', 'Head', 'Random', 'Traditional, functional, steeped in cultural value.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1858812362, 24, 'Polycarbonate helmet with tinted visor', 'Clothing', 'Head', 'Random', 'Now you can stare directly at the sun.', 2, 1);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (3811232691, 24, 'Polycarbonate nanoweave techie harness', 'Clothing', 'Outer chest', 'Legendary', 'I hear with the new cyberwear they’re coming up with in Chiba, you’re gonna be able to cram your body with more options than a frackin’ Zetatech aerodyne. Last guy in here, he wanted me to build him a cyberhand that had a built-in... aw, frack, you don’t wanna know. People want the weirdest stuff these days. If you can get parts, I can fix it. Count on it, chombatta. – Mister Ice, Head of Design, Technix, Inc.', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (790474942, 25, 'Polycarbonate nomad shirt with reinforced seams', 'Clothing', 'Inner chest', 'Legendary', 'We don’t have a home except the Caravan. We don’t have rights except what we take. We get run out of town by the cops; we get raided by the roadwarrior packs, and we survive because we’ve got guns and bikes…There’s kids, old men and women—families here. This ain’t no boostergang. These people are my family. – Nomad Santiago', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (4172116829, 26, 'Polycarbonate opti-enhanced fixer glasses', 'Clothing', 'Face', 'Legendary', 'Don’t give me this "Robin Hood" stuff. I’m doin’ a job, no more. I give people what they want, an’ they pay me out. Maybe I even a few scores here and there, but that’s good for business. I got a slogan... “How much you pay me? – Phil "Nacho" Hernandez, Fixer', 2, 0);
