INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (1591934908, 24, 'Ultralight tear-resistant nomad pants', 'Clothing', 'Legs', 'Legendary', 'We don’t have a home except the Caravan. We don’t have rights except what we take. We get run out of town by the cops; we get raided by the roadwarrior packs, and we survive because we’ve got guns and bikes…There’s kids, old men and women—families here. This ain’t no boostergang. These people are my family. – Nomad Santiago', 2, 0);
INSERT OR REPLACE INTO item (hash, length, name, category, type, quality, description, shape, expansion) VALUES (859406580, 24, 'Ultrathin composite-print solo shirt', 'Clothing', 'Inner chest', 'Legendary', 'After a few months on the Street, I got into a dustdown with a local Booster lord. I flatlined him and went back to my drink. Within ten minutes, the recruiter from Militech came up to me and dropped a business card... Now I’m a company man. – Morgan Blackhand, Solo', 2, 0);
